    private static readonly string[] Operations =
    ["Exp", "ExpM1", "Exp2", "Exp2M1", "Exp10", "Exp10M1", "Log", "LogP1", "Log2", "Log2P1", "Log10", "Log10P1", "Sin", "Cos", "Tan", "Asin", "Acos", "Atan", "Sinh", "Cosh", "Tanh", "Asinh", "Acosh", "Atanh", "Cbrt", "SinPi", "CosPi", "TanPi", "AsinPi", "AcosPi", "AtanPi", "Atan2", "Atan2Pi", "Pow", "PowR", "PowN", "RootN", "Compound", "Hypot", "ReciprocalSqrt"];

    public static IEnumerable<object[]> FormatsAndModes()
    {
        foreach (int format in new[] { 32, 64, 128 })
        foreach (var mode in Enum.GetValues<IeeeDecimalRounding>()) yield return [format, mode];
    }

    public static IEnumerable<object[]> MpfrRows()
    {
        foreach (var configuration in FormatsAndModes())
        foreach (string line in References.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            string[] row = line.Split('|');
            yield return [configuration[0], configuration[1], row[0], row[1], row[2], int.Parse(row[3], CultureInfo.InvariantCulture), row[4] == "1", row[5], row[6], row[7]];
        }
    }

    [Theory, MemberData(nameof(MpfrRows))]
    public void IndependentMpfrReference(int format, IeeeDecimalRounding mode, string operation, string input, string second, int n, bool exact, string reference, string lower, string upper)
    {
        if (format == 32) CheckReference<Decimal32>(mode, operation, input, second, n, exact, reference, lower, upper, EContext.Decimal32);
        else if (format == 64) CheckReference<Decimal64>(mode, operation, input, second, n, exact, reference, lower, upper, EContext.Decimal64);
        else CheckReference<Decimal128>(mode, operation, input, second, n, exact, reference, lower, upper, EContext.Decimal128);
    }

    private static void CheckReference<T>(IeeeDecimalRounding mode, string operation, string input, string second, int n, bool exact, string reference, string lower, string upper, EContext format)
        where T : struct, IFloatingPointIeee754<T>
    {
        var context = format.WithRounding(OracleMode(mode));
        var lowerBound = EDecimal.FromString(lower); var upperBound = EDecimal.FromString(upper);
        Assert.True(lowerBound.CompareTo(upperBound) <= 0);
        var expected = lowerBound.RoundToPrecision(context);
        Assert.True(expected.CompareTo(upperBound.RoundToPrecision(context)) == 0, $"Ambiguous MPFR enclosure for {operation}/{typeof(T).Name}/{mode}");
        Assert.True(lowerBound.CompareTo(EDecimal.FromString(reference)) <= 0 && upperBound.CompareTo(EDecimal.FromString(reference)) >= 0);
        var actual = Call(operation, Parse<T>(input), Parse<T>(second), n, new(mode));
        Assert.True(actual.IsSuccess, $"{operation}({input},{second},{n}) {typeof(T).Name}/{mode}: {actual.Error}");
        Assert.Equal(Parse<T>(expected.ToString()), actual.Value);
        Assert.Equal(exact ? IeeeDecimalFlags.None : IeeeDecimalFlags.Inexact, actual.Flags);
    }

    [Theory, MemberData(nameof(FormatsAndModes))]
    public void EveryApiValidatesContextAndPropagatesRawNaNs(int format, IeeeDecimalRounding mode)
    {
        if (format == 32) CheckNaNs<Decimal32>(mode); else if (format == 64) CheckNaNs<Decimal64>(mode); else CheckNaNs<Decimal128>(mode);
    }

    private static void CheckNaNs<T>(IeeeDecimalRounding mode) where T : struct, IFloatingPointIeee754<T>
    {
        T quiet = IeeeDecimal<T>.CreateNaN(123).Value, signaling = IeeeDecimal<T>.CreateNaN(321, signaling: true).Value;
        foreach (string operation in Operations)
        {
            foreach (bool isSignaling in new[] { false, true })
            {
                var result = Call(operation, isSignaling ? signaling : quiet, T.CreateChecked(2), 3, new(mode));
                Assert.True(result.IsSuccess); Assert.True(T.IsNaN(result.Value));
                Assert.Equal(isSignaling ? IeeeDecimalFlags.Invalid : IeeeDecimalFlags.None, result.Flags);
                Assert.False(IeeeDecimal<T>.IsSignaling(result.Value).Value);
                Assert.Equal(new BigInteger(isSignaling ? 321 : 123), IeeeDecimal<T>.GetPayload(result.Value).Value);
            }
            var trapped = Call(operation, signaling, T.CreateChecked(2), 3, new(mode, IeeeDecimalFlags.Invalid));
            Assert.False(trapped.IsSuccess); Assert.False(trapped.TryGetValue(out var cleared)); Assert.Equal(default, cleared);
            Assert.Equal(IeeeDecimalFlags.Invalid, trapped.Flags);
            Assert.Equal(ArithmeticError.OutOfRange, Call(operation, signaling, T.One, 3, new((IeeeDecimalRounding)99)).Error);
            Assert.Equal(ArithmeticError.OutOfRange, Call(operation, quiet, T.One, 3, new(mode, (IeeeDecimalFlags)128)).Error);
            Assert.Equal(ArithmeticError.OutOfRange, Call(operation, 0.5, 2.0, 3, new(mode)).Error);
        }
    }

    [Theory, MemberData(nameof(FormatsAndModes))]
    public void SignedZerosDomainsAndPoles(int format, IeeeDecimalRounding mode)
    {
        if (format == 32) CheckDomains<Decimal32>(mode); else if (format == 64) CheckDomains<Decimal64>(mode); else CheckDomains<Decimal128>(mode);
    }

    private static void CheckDomains<T>(IeeeDecimalRounding mode) where T : struct, IFloatingPointIeee754<T>
    {
        var c = new IeeeDecimalContext(mode);
        string[] oddZero = ["Sin", "Tan", "SinPi", "TanPi", "Asin", "Atan", "AsinPi", "AtanPi", "Sinh", "Tanh", "Asinh", "Atanh", "ExpM1", "Exp2M1", "Exp10M1", "LogP1", "Log2P1", "Log10P1", "Cbrt", "Pow", "PowN", "RootN", "Atan2", "Atan2Pi"];
        foreach (string op in oddZero)
        foreach (bool negative in new[] { false, true })
        {
            T zero = negative ? T.NegativeZero : T.Zero;
            T second = op is "Atan2" or "Atan2Pi" ? T.One : T.CreateChecked(3);
            var result = Call(op, zero, second, 3, c);
            Assert.Equal(T.Zero, result.Value); Assert.Equal(negative, T.IsNegative(result.Value)); Assert.Equal(IeeeDecimalFlags.None, result.Flags);
        }
        foreach (string op in new[] { "Cos", "CosPi", "Cosh", "Exp", "Exp2", "Exp10", "Compound" })
        { var r = Call(op, T.NegativeZero, T.One, 3, c); Assert.Equal(T.One, r.Value); Assert.Equal(IeeeDecimalFlags.None, r.Flags); }
        Assert.Equal(Parse<T>("0.5"), Call("AcosPi", T.NegativeZero, T.One, 3, c).Value);
        foreach (string op in new[] { "Log", "Log2", "Log10" })
        {
            var pole = Call(op, T.NegativeZero, T.One, 3, c); Assert.True(T.IsNegativeInfinity(pole.Value)); Assert.Equal(IeeeDecimalFlags.DivisionByZero, pole.Flags);
            Invalid(Call(op, -T.One, T.One, 3, c));
        }
        foreach (string op in new[] { "LogP1", "Log2P1", "Log10P1" })
        {
            var pole = Call(op, -T.One, T.One, 3, c); Assert.True(T.IsNegativeInfinity(pole.Value)); Assert.Equal(IeeeDecimalFlags.DivisionByZero, pole.Flags);
            Invalid(Call(op, -T.CreateChecked(2), T.One, 3, c));
        }
        foreach (string op in new[] { "Asin", "Acos", "AsinPi", "AcosPi", "Atanh" })
        { Invalid(Call(op, T.CreateChecked(2), T.One, 3, c)); Invalid(Call(op, -T.CreateChecked(2), T.One, 3, c)); }
        Invalid(Call("Acosh", T.Zero, T.One, 3, c)); Invalid(Call("Acosh", Parse<T>("0.5"), T.One, 3, c));
        Invalid(Call("ReciprocalSqrt", -T.One, T.One, 3, c));
        Invalid(Call("Pow", -T.CreateChecked(2), Parse<T>("0.5"), 3, c));
        Invalid(Call("PowR", -T.CreateChecked(2), T.CreateChecked(2), 3, c));
        Invalid(Call("RootN", -T.CreateChecked(2), T.One, 4, c)); Invalid(Call("RootN", T.One, T.One, 0, c));
        Invalid(Call("Compound", -T.CreateChecked(2), T.One, 0, c));
        foreach (bool negative in new[] { false, true })
        {
            T one = negative ? -T.One : T.One, zero = negative ? T.NegativeZero : T.Zero;
            foreach (string op in new[] { "Atanh", "ReciprocalSqrt", "RootN", "Pow", "PowN" })
            {
                var r = Call(op, op == "Atanh" ? one : zero, -T.CreateChecked(3), -3, c);
                Assert.True(T.IsInfinity(r.Value)); Assert.Equal(negative, T.IsNegative(r.Value)); Assert.Equal(IeeeDecimalFlags.DivisionByZero, r.Flags);
            }
        }
        var negativeBaseZero = Call("PowR", T.NegativeZero, -T.CreateChecked(3), 3, c);
        Assert.True(T.IsPositiveInfinity(negativeBaseZero.Value)); Assert.Equal(IeeeDecimalFlags.DivisionByZero, negativeBaseZero.Flags);
    }

    [Theory, MemberData(nameof(FormatsAndModes))]
    public void InfinityRulesAndExactPiLattice(int format, IeeeDecimalRounding mode)
    {
        if (format == 32) CheckInfinity<Decimal32>(mode); else if (format == 64) CheckInfinity<Decimal64>(mode); else CheckInfinity<Decimal128>(mode);
    }

    private static void CheckInfinity<T>(IeeeDecimalRounding mode) where T : struct, IFloatingPointIeee754<T>
    {
        var c = new IeeeDecimalContext(mode);
        foreach (bool negative in new[] { false, true })
        {
            T infinity = negative ? T.NegativeInfinity : T.PositiveInfinity;
            foreach (string op in new[] { "Exp", "Exp2", "Exp10", "ExpM1", "Exp2M1", "Exp10M1" })
            {
                var r = Call(op, infinity, T.One, 3, c);
                Assert.Equal(negative ? op.EndsWith("M1", StringComparison.Ordinal) ? -T.One : T.Zero : T.PositiveInfinity, r.Value); Assert.Equal(IeeeDecimalFlags.None, r.Flags);
            }
            foreach (string op in new[] { "Log", "Log2", "Log10", "LogP1", "Log2P1", "Log10P1", "Acosh" })
            { var r = Call(op, infinity, T.One, 3, c); if (negative) Invalid(r); else { Assert.True(T.IsPositiveInfinity(r.Value)); Assert.Equal(IeeeDecimalFlags.None, r.Flags); } }
            foreach (string op in new[] { "Sin", "Cos", "Tan", "SinPi", "CosPi", "TanPi", "Asin", "Acos", "AsinPi", "AcosPi", "Atanh" }) Invalid(Call(op, infinity, T.One, 3, c));
            foreach (string op in new[] { "Sinh", "Asinh", "Cbrt", "RootN", "PowN", "Pow" })
            { var r = Call(op, infinity, T.CreateChecked(3), 3, c); Assert.Equal(infinity, r.Value); Assert.Equal(IeeeDecimalFlags.None, r.Flags); }
            Assert.Equal(T.PositiveInfinity, Call("Cosh", infinity, T.One, 3, c).Value);
            Assert.Equal(negative ? -T.One : T.One, Call("Tanh", infinity, T.One, 3, c).Value);
            Assert.Equal(negative ? Parse<T>("-0.5") : Parse<T>("0.5"), Call("AtanPi", infinity, T.One, 3, c).Value);
            var root = Call("RootN", infinity, T.One, -3, c); Assert.Equal(T.Zero, root.Value); Assert.Equal(negative, T.IsNegative(root.Value));
            var reciprocal = Call("ReciprocalSqrt", infinity, T.One, 3, c); if (negative) Invalid(reciprocal); else { Assert.Equal(T.Zero, reciprocal.Value); Assert.Equal(IeeeDecimalFlags.None, reciprocal.Flags); }
        }
        foreach (string s in new[] { "1", "2", "-1", "-2", "1000000", "-1000000" })
        {
            T x = Parse<T>(s); var sin = Call("SinPi", x, T.One, 3, c); Assert.Equal(T.Zero, sin.Value); Assert.Equal(T.IsNegative(x), T.IsNegative(sin.Value)); Assert.Equal(IeeeDecimalFlags.None, sin.Flags);
        }
        foreach (string s in new[] { "0.5", "1.5", "-0.5", "-1.5" })
        { var cos = Call("CosPi", Parse<T>(s), T.One, 3, c); Assert.Equal(T.Zero, cos.Value); Assert.False(T.IsNegative(cos.Value)); Assert.Equal(IeeeDecimalFlags.None, cos.Flags); }
        foreach (var pair in new[] { ("0.5", false), ("1.5", true), ("-0.5", true), ("-1.5", false) })
        { var tan = Call("TanPi", Parse<T>(pair.Item1), T.One, 3, c); Assert.True(T.IsInfinity(tan.Value)); Assert.Equal(pair.Item2, T.IsNegative(tan.Value)); Assert.Equal(IeeeDecimalFlags.DivisionByZero, tan.Flags); }
        foreach (var pair in new[] { ("1", true), ("2", false), ("-1", false), ("-2", true) })
        { var tan = Call("TanPi", Parse<T>(pair.Item1), T.One, 3, c); Assert.Equal(T.Zero, tan.Value); Assert.Equal(pair.Item2, T.IsNegative(tan.Value)); Assert.Equal(IeeeDecimalFlags.None, tan.Flags); }
        foreach (var pair in new[] { ("0.25", "1"), ("0.75", "-1"), ("-0.25", "-1"), ("-0.75", "1") })
        { var tan = Call("TanPi", Parse<T>(pair.Item1), T.One, 3, c); Assert.Equal(Parse<T>(pair.Item2), tan.Value); Assert.Equal(IeeeDecimalFlags.None, tan.Flags); }
        var qnan = IeeeDecimal<T>.CreateNaN(12).Value; var snan = IeeeDecimal<T>.CreateNaN(13, signaling: true).Value;
        Assert.Equal(T.PositiveInfinity, Call("Hypot", T.PositiveInfinity, qnan, 3, c).Value);
        Invalid(Call("Hypot", T.PositiveInfinity, snan, 3, c));
    }

    [Theory, MemberData(nameof(FormatsAndModes))]
    public void BoundedHugeCutoffsPreserveDirectedRoundingAndFlags(int format, IeeeDecimalRounding mode)
    {
        if (format == 32) CheckCutoffs<Decimal32>(mode, EContext.Decimal32, 7); else if (format == 64) CheckCutoffs<Decimal64>(mode, EContext.Decimal64, 16); else CheckCutoffs<Decimal128>(mode, EContext.Decimal128, 34);
    }

    private static void CheckCutoffs<T>(IeeeDecimalRounding mode, EContext format, int precision) where T : struct, IFloatingPointIeee754<T>
    {
        // These arguments choose documented range shortcuts; they do not request an
        // unbounded exponential or an impractically large exact integer power.
        var c = new IeeeDecimalContext(mode); T huge = Parse<T>("100001");
        var referenceContext = format.WithRounding(OracleMode(mode));
        T overflow = FromOracle<T>(EDecimal.FromString("1e10000").RoundToPrecision(referenceContext));
        T negativeOverflow = FromOracle<T>(EDecimal.FromString("-1e10000").RoundToPrecision(referenceContext));
        T underflow = FromOracle<T>(EDecimal.FromString("1e-10000").RoundToPrecision(referenceContext));
        foreach (string op in new[] { "Exp", "Exp2", "Exp10", "ExpM1", "Exp2M1", "Exp10M1" })
        { var r = Call(op, huge, T.One, 3, c); Assert.Equal(overflow, r.Value); Assert.Equal(IeeeDecimalFlags.Overflow | IeeeDecimalFlags.Inexact, r.Flags); }
        foreach (string op in new[] { "Exp", "Exp2", "Exp10" })
        { var r = Call(op, -huge, T.One, 3, c); Assert.Equal(underflow, r.Value); Assert.Equal(IeeeDecimalFlags.Underflow | IeeeDecimalFlags.Inexact, r.Flags); }
        foreach (string op in new[] { "Sinh", "Cosh" })
        foreach (bool negative in new[] { false, true })
        { var r = Call(op, negative ? -huge : huge, T.One, 3, c); Assert.Equal(negative && op == "Sinh" ? negativeOverflow : overflow, r.Value); Assert.Equal(IeeeDecimalFlags.Overflow | IeeeDecimalFlags.Inexact, r.Flags); }
        T belowOne = Parse<T>("0." + new string('9', precision));
        foreach (string op in new[] { "ExpM1", "Exp2M1", "Exp10M1" })
        { var r = Call(op, -huge, T.One, 3, c); Assert.Equal(mode is IeeeDecimalRounding.TowardPositive or IeeeDecimalRounding.TowardZero ? -belowOne : -T.One, r.Value); Assert.Equal(IeeeDecimalFlags.Inexact, r.Flags); }
        foreach (bool negative in new[] { false, true })
        {
            var r = Call("Tanh", negative ? -Parse<T>("201") : Parse<T>("201"), T.One, 3, c);
            bool adjacent = mode == IeeeDecimalRounding.TowardZero || mode == (negative ? IeeeDecimalRounding.TowardPositive : IeeeDecimalRounding.TowardNegative);
            T magnitude = adjacent ? belowOne : T.One;
            Assert.Equal(negative ? -magnitude : magnitude, r.Value); Assert.Equal(IeeeDecimalFlags.Inexact, r.Flags);
        }
        var trapped = Call("Exp", huge, T.One, 3, new(mode, IeeeDecimalFlags.Overflow));
        Assert.False(trapped.IsSuccess); Assert.Equal(IeeeDecimalFlags.Overflow | IeeeDecimalFlags.Inexact, trapped.Flags);
        var tinyTrap = Call("Exp", -huge, T.One, 3, new(mode, IeeeDecimalFlags.Underflow));
        Assert.False(tinyTrap.IsSuccess); Assert.Equal(IeeeDecimalFlags.Underflow | IeeeDecimalFlags.Inexact, tinyTrap.Flags);
    }

    [Theory, MemberData(nameof(FormatsAndModes))]
    public void ExactIdentitiesPreferredQuantumAndPowerSpecials(int format, IeeeDecimalRounding mode)
    {
        if (format == 32) CheckExact<Decimal32>(mode); else if (format == 64) CheckExact<Decimal64>(mode); else CheckExact<Decimal128>(mode);
    }

    private static void CheckExact<T>(IeeeDecimalRounding mode) where T : struct, IFloatingPointIeee754<T>
    {
        var c = new IeeeDecimalContext(mode);
        foreach (var row in new[] {
            ("Exp2", "3", "0", 3, "8"), ("Exp2", "-3", "0", 3, "0.125"),
            ("Exp2M1", "3", "0", 3, "7"), ("Exp2M1", "-3", "0", 3, "-0.875"),
            ("Exp10", "3", "0", 3, "1000"), ("Exp10", "-3", "0", 3, "0.001"),
            ("Exp10M1", "3", "0", 3, "999"), ("Exp10M1", "-3", "0", 3, "-0.999"),
            ("Log2", "128", "0", 3, "7"), ("Log2", "0.125", "0", 3, "-3"),
            ("Log10", "100.0", "0", 3, "2"), ("Log10", "0.001", "0", 3, "-3"),
            ("Log2P1", "3", "0", 3, "2"), ("Log10P1", "99", "0", 3, "2"),
            ("Acos", "1", "0", 3, "0"), ("Acosh", "1", "0", 3, "0"),
            ("Hypot", "3.00", "4.0", 3, "5.00"), ("ReciprocalSqrt", "0.04", "0", 3, "5"),
            ("RootN", "64", "0", 3, "4"), ("RootN", "-8", "0", 3, "-2"),
            ("RootN", "16", "0", -2, "0.25"), ("RootN", "1", "0", int.MinValue, "1"),
            ("PowN", "-1", "0", int.MaxValue, "-1"), ("PowN", "1", "0", int.MinValue, "1"),
            ("Compound", "0", "0", int.MinValue, "1"), ("Compound", "0.1", "0", -2, "0.8264462809917355371900826446280991735537") })
        {
            // The final compound reciprocal is not finite decimal: qualify its value via
            // an independent rational oracle and expect Inexact, rather than a decimal literal.
            bool rational = row.Item1 == "Compound" && row.Item2 == "0.1";
            EDecimal expected = rational ? EDecimal.FromString("100").Divide(EDecimal.FromString("121"), TargetContext<T>().WithRounding(OracleMode(mode))) : EDecimal.FromString(row.Item5);
            var r = Call(row.Item1, Parse<T>(row.Item2), Parse<T>(row.Item3), row.Item4, c);
            Assert.Equal(FromOracle<T>(expected), r.Value); Assert.Equal(rational ? IeeeDecimalFlags.Inexact : IeeeDecimalFlags.None, r.Flags);
        }
        foreach (var row in new[] { ("Pow", "1.00", "2", 2, -4), ("PowN", "-1.00", "0", 2, -4), ("RootN", "1.00", "0", 3, -1), ("Compound", "0.00", "0", 2, -4), ("Hypot", "3.00", "4.0", 3, -2), ("Pow", "4.00", "0.5", 3, -1) })
        { var r = Call(row.Item1, Parse<T>(row.Item2), Parse<T>(row.Item3), row.Item4, c); Assert.Equal(IeeeDecimalFlags.None, r.Flags); Assert.Equal(row.Item5, IeeeDecimal<T>.Quantum(r.Value).Value); }
        T quiet = IeeeDecimal<T>.CreateNaN(5).Value, signaling = IeeeDecimal<T>.CreateNaN(6, signaling: true).Value;
        Assert.Equal(T.One, Call("Pow", quiet, T.Zero, 3, c).Value);
        Invalid(Call("Pow", signaling, T.Zero, 3, c));
        Assert.Equal(T.One, Call("PowN", quiet, T.One, 0, c).Value);
        Invalid(Call("PowN", signaling, T.One, 0, c));
        foreach (T basis in new[] { Parse<T>("0.5"), Parse<T>("2"), Parse<T>("-0.5"), Parse<T>("-2"), T.One, -T.One })
        foreach (bool negativeExponent in new[] { false, true })
        {
            var r = Call("Pow", basis, negativeExponent ? T.NegativeInfinity : T.PositiveInfinity, 3, c);
            bool one = T.Abs(basis) == T.One, infinite = T.Abs(basis) > T.One != negativeExponent;
            Assert.Equal(one ? T.One : infinite ? T.PositiveInfinity : T.Zero, r.Value); Assert.Equal(IeeeDecimalFlags.None, r.Flags);
        }
        Invalid(Call("PowR", T.Zero, T.Zero, 3, c)); Invalid(Call("PowR", T.One, T.PositiveInfinity, 3, c)); Invalid(Call("PowR", T.PositiveInfinity, T.Zero, 3, c));
        var zeroRoot = Call("RootN", T.NegativeZero, T.One, 2, c); Assert.Equal(T.Zero, zeroRoot.Value); Assert.False(T.IsNegative(zeroRoot.Value));
    }

    [Theory, MemberData(nameof(FormatsAndModes))]
    public void SurvivorCounterexamplesForExactPowersQuantumAndPiLattice(int format, IeeeDecimalRounding mode)
    {
        if (format == 32) CheckSurvivors<Decimal32>(mode); else if (format == 64) CheckSurvivors<Decimal64>(mode); else CheckSurvivors<Decimal128>(mode);
    }

    private static void CheckSurvivors<T>(IeeeDecimalRounding mode) where T : struct, IFloatingPointIeee754<T>
    {
        var c = new IeeeDecimalContext(mode);
        // Exact identities independently fix values, signs and preferred quantum. These
        // challenge campaign02 mutants1834,1592,1602,1628,1633,1699,1737 and1960.
        foreach (var row in new[] {
            ("Pow", "0.25", "-5", 0, "1024", 0), ("PowN", "0.25", "0", -5, "1024", 0),
            ("Pow", "0.010", "2", 0, "0.000100", -6), ("PowN", "0.010", "0", 2, "0.000100", -6),
            ("Pow", "0.010", "-2", 0, "1E4", 4), ("PowN", "0.010", "0", -2, "1E4", 4),
            ("Pow", "-0.2", "-3", 0, "-125", 0), ("PowN", "-0.2", "0", -3, "-125", 0),
            ("Pow", "4.0", "0.5", 0, "2.0", -1), ("PowR", "4.0", "0.5", 0, "2.0", -1),
            ("Pow", "0.0004", "-0.5", 0, "5E1", 1),
            ("Pow", "0.0016", "0.75", 0, "0.008", -3), ("Pow", "0.0016", "-0.75", 0, "125", 0),
            ("RootN", "-0.008", "0", -3, "-5", 0), ("RootN", "-0.008", "0", 3, "-0.2", -1),
            ("RootN", "0.000064", "0", 3, "0.04", -2), ("RootN", "64.000", "0", 3, "4.0", -1),
            ("RootN", "8E3", "0", 3, "2E1", 1), ("RootN", "8E3", "0", -3, "0.05", -2),
            ("RootN", "0.0004", "0", -2, "5E1", 1), ("ReciprocalSqrt", "0.0004", "0", 0, "5E1", 1),
            ("Pow", "1.00", "-2", 0, "1", 0), ("PowN", "-1.00", "0", -3, "-1", 0),
            ("RootN", "1.00", "0", -3, "1", 0),
            ("Pow", "2E1", "3", 0, "8E3", 3), ("PowN", "2E1", "0", 3, "8E3", 3),
            ("Pow", "2E1", "-3", 0, "0.000125", -6), ("PowN", "2E1", "0", -3, "0.000125", -6) })
        {
            var result = Call(row.Item1, Parse<T>(row.Item2), Parse<T>(row.Item3), row.Item4, c);
            Assert.Equal(Parse<T>(row.Item5), result.Value); Assert.Equal(IeeeDecimalFlags.None, result.Flags);
            Assert.Equal(row.Item6, IeeeDecimal<T>.Quantum(result.Value).Value);
        }
        // PeterO is independent of the production exact-power/root code. Nonzero source
        // quantum and a negative power catch decimal-exponent sign/scale mutations.
        foreach (string input in new[] { "0.25", "0.010", "-0.2", "2E1" })
        foreach (int power in new[] { -5, -3, -2, 2, 3, 5 })
        {
            var oracleContext = TargetContext<T>().WithRounding(OracleMode(mode)).WithBlankFlags();
            EDecimal expected = EDecimal.FromString(input).Pow(power, oracleContext);
            foreach (string operation in new[] { "Pow", "PowN" })
            {
                var actual = Call(operation, Parse<T>(input), T.CreateChecked(power), power, c);
                Assert.Equal(Parse<T>(expected.ToString()), actual.Value);
                Assert.Equal((oracleContext.Flags & EContext.FlagInexact) != 0, (actual.Flags & IeeeDecimalFlags.Inexact) != 0);
            }
        }
        foreach (var row in new[] { ("0.5", "1"), ("1.5", "-1"), ("2.5", "1"), ("-0.5", "-1"), ("-1.5", "1"), ("-2.5", "-1") })
        {
            var sin = Call("SinPi", Parse<T>(row.Item1), T.One, 3, c);
            Assert.Equal(Parse<T>(row.Item2), sin.Value); Assert.Equal(IeeeDecimalFlags.None, sin.Flags);
        }
        foreach (var row in new[] { ("0", "1"), ("1", "-1"), ("2", "1"), ("-1", "-1"), ("-2", "1"), ("1E2", "1") })
        {
            var cos = Call("CosPi", Parse<T>(row.Item1), T.One, 3, c);
            Assert.Equal(Parse<T>(row.Item2), cos.Value); Assert.Equal(IeeeDecimalFlags.None, cos.Flags);
        }
        foreach (var row in new[] { ("Log2P1", "-0.5", "-1"), ("Log2P1", "-0.75", "-2"), ("Log10P1", "-0.9", "-1"), ("Log10P1", "-0.99", "-2"), ("Log2", "1.28E2", "7") })
        {
            var result = Call(row.Item1, Parse<T>(row.Item2), T.One, 3, c);
            Assert.Equal(Parse<T>(row.Item3), result.Value); Assert.Equal(IeeeDecimalFlags.None, result.Flags);
        }
        foreach (var row in new[] { ("Pow", "1.0", "1E1", 10, typeof(T) == typeof(Decimal32) ? -6 : -10), ("Pow", "1.000", "0.5", 0, -2) })
        {
            var expected = EDecimal.FromString(row.Item2).Pow(EDecimal.FromString(row.Item3), TargetContext<T>().WithRounding(OracleMode(mode)));
            var result = Call(row.Item1, Parse<T>(row.Item2), Parse<T>(row.Item3), row.Item4, c);
            Assert.Equal(Parse<T>(expected.ToString()), result.Value);
            Assert.Equal(row.Item5, IeeeDecimal<T>.Quantum(result.Value).Value);
        }
        var identity = Call("RootN", Parse<T>("-3.250"), T.One, 1, c);
        Assert.Equal(IeeeDecimal<T>.EncodeBinary(Parse<T>("-3.250")).Value, IeeeDecimal<T>.EncodeBinary(identity.Value).Value);
        Assert.Equal(IeeeDecimalFlags.None, identity.Flags);
        Assert.Equal(-T.One, Call("PowN", -T.One, T.One, int.MaxValue, c).Value);
        Assert.Equal(T.One, Call("PowN", -T.One, T.One, int.MinValue, c).Value);
    }

    [Theory, MemberData(nameof(FormatsAndModes))]
    public void CoreSpecialValuesQuadrantsAndUnsupportedCarrierOrdering(int format, IeeeDecimalRounding mode)
    {
        if (format == 32) CheckCoreSpecials<Decimal32>(mode); else if (format == 64) CheckCoreSpecials<Decimal64>(mode); else CheckCoreSpecials<Decimal128>(mode);
    }

    private static void CheckCoreSpecials<T>(IeeeDecimalRounding mode) where T : struct, IFloatingPointIeee754<T>
    {
        var c = new IeeeDecimalContext(mode);
        foreach (string operation in Operations)
        {
            // Unsupported source-format rejection must precede NaN decoding or generic
            // arithmetic, including paths that would otherwise suppress/propagate NaNs.
            var unsupported = Call(operation, double.NaN, double.NaN, 3, c);
            Assert.Equal(ArithmeticError.OutOfRange, unsupported.Error); Assert.Equal(IeeeDecimalFlags.None, unsupported.Flags);
            Assert.False(unsupported.TryGetValue(out var value)); Assert.Equal(0d, value);
        }
        foreach (var row in new[] { ("AsinPi", "-1", "-0.5"), ("AsinPi", "1", "0.5"), ("AcosPi", "1", "0"), ("AcosPi", "-1", "1"), ("AtanPi", "1", "0.25"), ("AtanPi", "-1", "-0.25") })
        { var r = Call(row.Item1, Parse<T>(row.Item2), T.One, 3, c); Assert.Equal(Parse<T>(row.Item3), r.Value); Assert.Equal(IeeeDecimalFlags.None, r.Flags); }
        foreach (var row in new[] { ("1", "inf", "0"), ("-1", "inf", "-0"), ("1", "-inf", "1"), ("-1", "-inf", "-1"), ("inf", "2", "0.5"), ("-inf", "2", "-0.5"), ("inf", "inf", "0.25"), ("inf", "-inf", "0.75"), ("-inf", "inf", "-0.25"), ("-inf", "-inf", "-0.75") })
        {
            var r = Call("Atan2Pi", Parse<T>(row.Item1), Parse<T>(row.Item2), 3, c); T expected = Parse<T>(row.Item3);
            Assert.Equal(expected, r.Value); Assert.Equal(T.IsNegative(expected), T.IsNegative(r.Value)); Assert.Equal(IeeeDecimalFlags.None, r.Flags);
        }
        // Reflect independent MPFR bounds before decimal rounding. This challenges the
        // positive-y/negative-x branch instead of reusing the same production function as oracle.
        foreach (string op in new[] { "Atan2", "Atan2Pi" })
        {
            string line = References.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).First(s => s.StartsWith(op + "|-0.5|-2|", StringComparison.Ordinal));
            string[] fixture = line.Split('|');
            EDecimal lower = EDecimal.FromString(fixture[7]).Negate(), upper = EDecimal.FromString(fixture[6]).Negate();
            var target = TargetContext<T>().WithRounding(OracleMode(mode));
            var expected = lower.RoundToPrecision(target);
            Assert.True(expected.CompareTo(upper.RoundToPrecision(target)) == 0);
            var actual = Call(op, Parse<T>("0.5"), Parse<T>("-2"), 3, c);
            Assert.Equal(Parse<T>(expected.ToString()), actual.Value); Assert.Equal(IeeeDecimalFlags.Inexact, actual.Flags);
        }
        var zero = Call("Compound", Parse<T>("-1.00"), T.One, 3, c);
        Assert.Equal(T.Zero, zero.Value); Assert.False(T.IsNegative(zero.Value)); Assert.Equal(-6, IeeeDecimal<T>.Quantum(zero.Value).Value); Assert.Equal(IeeeDecimalFlags.None, zero.Flags);
        var one = Call("Compound", -T.One, T.One, 0, c); Assert.Equal(T.One, one.Value); Assert.Equal(IeeeDecimalFlags.None, one.Flags);
        var pole = Call("Compound", -T.One, T.One, -3, c); Assert.True(T.IsPositiveInfinity(pole.Value)); Assert.Equal(IeeeDecimalFlags.DivisionByZero, pole.Flags);
    }

    private static EContext TargetContext<T>() => typeof(T) == typeof(Decimal32) ? EContext.Decimal32 : typeof(T) == typeof(Decimal64) ? EContext.Decimal64 : EContext.Decimal128;
    private static T FromOracle<T>(EDecimal value) where T : struct, IFloatingPointIeee754<T> => value.IsInfinity() ? value.IsNegative ? T.NegativeInfinity : T.PositiveInfinity : Parse<T>(value.ToString());

    private static void Invalid<T>(IeeeDecimalResult<T> result) where T : struct, IFloatingPointIeee754<T>
    { Assert.True(result.IsSuccess); Assert.True(T.IsNaN(result.Value)); Assert.Equal(IeeeDecimalFlags.Invalid, result.Flags); }

    private static T Parse<T>(string text) where T : struct, IFloatingPointIeee754<T> =>
        text == "inf" ? T.PositiveInfinity : text == "-inf" ? T.NegativeInfinity : T.Parse(text, CultureInfo.InvariantCulture);
    private static ERounding OracleMode(IeeeDecimalRounding mode) => mode switch
    { IeeeDecimalRounding.ToNearestEven => ERounding.HalfEven, IeeeDecimalRounding.ToNearestAway => ERounding.HalfUp, IeeeDecimalRounding.TowardZero => ERounding.Down, IeeeDecimalRounding.TowardNegative => ERounding.Floor, _ => ERounding.Ceiling };

    private static IeeeDecimalResult<T> Call<T>(string op, T x, T y, int n, IeeeDecimalContext c) where T : struct, IFloatingPointIeee754<T> => op switch
    {
        "Exp" => IeeeDecimal<T>.Exp(x,c), "ExpM1" => IeeeDecimal<T>.ExpM1(x,c), "Exp2" => IeeeDecimal<T>.Exp2(x,c), "Exp2M1" => IeeeDecimal<T>.Exp2M1(x,c), "Exp10" => IeeeDecimal<T>.Exp10(x,c), "Exp10M1" => IeeeDecimal<T>.Exp10M1(x,c),
        "Log" => IeeeDecimal<T>.Log(x,c), "LogP1" => IeeeDecimal<T>.LogP1(x,c), "Log2" => IeeeDecimal<T>.Log2(x,c), "Log2P1" => IeeeDecimal<T>.Log2P1(x,c), "Log10" => IeeeDecimal<T>.Log10(x,c), "Log10P1" => IeeeDecimal<T>.Log10P1(x,c),
        "Sin" => IeeeDecimal<T>.Sin(x,c), "Cos" => IeeeDecimal<T>.Cos(x,c), "Tan" => IeeeDecimal<T>.Tan(x,c), "Asin" => IeeeDecimal<T>.Asin(x,c), "Acos" => IeeeDecimal<T>.Acos(x,c), "Atan" => IeeeDecimal<T>.Atan(x,c),
